    // 节点(小红书视频界面右边的工具栏)索引为0的子节点的索引为1的子节点的类名为 "android.widget.ImageView"
    -&gt;className(function ($it) {
        return $it == "android.widget.ImageView";
    });
// 节点(小红书视频界面右边的工具栏)索引为0的子节点的选择器
$child0Selector = $accessibility-&gt;createSelector()
    // 节点(小红书视频界面右边的工具栏)索引为0的子节点的类名为 `android.widget.Button`
    -&gt;className(function ($it) {
        return $it == "android.widget.Button";
    })
    // 通过 child 方法设置子节点的选择器, 第一个参数为索引，第二个参数为选择器
    -&gt;child(0, $child00Selector)
    // 通过 child 方法设置子节点的选择器, 第一个参数为索引，第二个参数为选择器
    -&gt;child(1, $child01Selector);
// 定义一个选择器用于选择小红书视频界面右边工具栏，包含了`点赞`、`收藏`、`分享`等信息
$selector = $accessibility-&gt;createSelector()
    // 节点(小红书视频界面右边的工具栏)的类名是`android.widget.LinearLayout`
    -&gt;className(function ($it) {
        return $it == "android.widget.LinearLayout";
    })
    // 通过 parent 方法设置父节点的选择器
    -&gt;parent($parentSelector)
    // 通过 child 方法设置子节点的选择器, 第一个参数为索引，第二个参数为选择器
    -&gt;child(0, $child0Selector);
// 通过选择的 findOne 方法查找节点，如果没有找到则返回 null, 第一个参数为虚拟屏幕 id, android 11(api 30) 以下的手机会忽略该参数, 0 表示主屏幕(物理屏幕镜像)，第二个参数为超时时间，单位为毫秒, 如果为负数, 查找一次直接返回, 无论有没有节点满足条件, 如果为0, 则表示一直查找知道找到满足条件的节点, 如果为大于0的数值, 那么就会在该时间内返回, 无论有没有节点满足条件。
$node = $selector-&gt;findOne($display-&gt;getId(), -1);
// 获取点赞，评论以及收藏数量, 可以直接通过层次结构获取节点
if ($node != null) {
    // 节点(小红书视频界面右边的工具栏)索引为0的子节点的索引为0的子节点的为点赞数量
    $console-&gt;log(javaString("点赞"), $node-&gt;child(0)-&gt;child(0)-&gt;text());
    // 节点(小红书视频界面右边的工具栏)索引为1的子节点的索引为1的子节点的为评论数量
    $console-&gt;log(javaString("评论"), $node-&gt;child(1)-&gt;child(1)-&gt;text());
    // 节点(小红书视频界面右边的工具栏)索引为2的子节点的索引为1的子节点的为收藏数量

在大多数情况下，应用都具有无障碍节点（部分游戏除外），通过无障碍服务可以获取界面上的某个或某些节点，获取后可对其执行指定操作，例如点击、设置文本等。
M8Test 提供了无障碍服务组件，通过无障碍服务权限即可实现自动化操作。我们需要先在 build.gradle.kts 文件中引入该组件：
// 在脚本项目中引用 M8Test 组件
requireComponent {
// 无障碍组件
    name = "YumiMiyamotoAccessibility"
// 组件版本，可在 https://github.com/YumiMiyamoto/accessibility-release/releases/ 查看最新版本
    version = "0.1.3"
// 组件下载地址
    url =
        "https://github.com/YumiMiyamoto/accessibility-release/releases/download/Accessibility-$version/com.m8test.accessibility-release_$version.apk"
}
使用无障碍服务时，通常有三种方式（可参考《自动化》章节）：
2. 直接执行手势操作，即在屏幕上模拟点击、滑动等手势
4. 执行全局操作，例如返回、回到主页、显示通知栏等
6. 选择无障碍节点并对其进行操作，例如设置节点文本、点击节点、让节点获取焦点等，通常包含两个步骤：
- 选择节点：通过无障碍选择器筛选满足条件的节点
- 执行操作：对选中的节点进行点击、设置文本等操作
下面介绍该组件中的核心类，这些类提供了无障碍服务的核心功能，如获取界面节点、执行操作等。相关类的 API 接口文档可查看：https://yumimiyamoto.github.io/accessibility-release/

