使用 scope.withContext 可以在不同的线程池（调度器）之间安全地切换，而无需手动管理回调。
<b>kotlin</b> import com.m8test.script.GlobalVariables.*

_threads.getMain().setBackground(true)
// 修复：newScope 块移除显式参数 it -&gt;，直接调用 setDispatcher
val scope = _coroutines.newScope {
    setDispatcher { dispatchers -&gt; dispatchers.getDefault() }
}

// 修复：launch 块移除显式参数
scope.launch(null, null) {
    _console.log("当前在默认线程池上: " + Thread.currentThread().name)

    // 修复：withContext 的 contextBuilder 块移除显式参数
    withContext({
        // 在配置块中指定要切换到的调度器
        setDispatcher { dispatchers -&gt; dispatchers.getScriptMain() }
    }) {
        // 修复：block 移除显式参数 innerScope -&gt;
        // 这个闭包内的代码将在脚本主线程上执行
        _console.log("已切换到脚本主线程: " + Thread.currentThread().name)
        "脚本主线程"
    }

    // 修复：withContext 参数
    withContext({ setDispatcher { dispatchers -&gt; dispatchers.getAndroidMain() } }) {
        _console.log("已切换到 Android UI 线程: " + Thread.currentThread().name)
        "Android UI线程"
    }
}
