默认情况下，launch 和 async 会立即调度协程执行。但你可以通过 start 参数将其设置为懒加载模式，这样协程只会在被需要时（例如调用 job.start()）才真正开始。
<b>kotlin</b> import com.m8test.script.GlobalVariables.*

/*
 * 完整示例 6.4: 使用懒加载模式
 */

// --- 样板代码 ---
_threads.getMain().setBackground(true)
val scope = _coroutines.newScope(null)

_console.log("创建一个懒加载的 Deferred...")

// 使用 CoroutineStarts.getLazy() 来设置启动模式
// 注意：start 参数是 (CoroutineStarts) -&gt; CoroutineStart，这里需要保留参数 starts -&gt;
// 修复：block 参数是 CoroutineScope.() -&gt; T，需要移除 s -&gt;
val lazyDeferred = scope.async(null, { starts -&gt; starts.getLazy() }) {
    _console.log("懒加载的协程现在才真正开始执行！")
    delay(1500).then { innerScope, _ -&gt; innerScope.resolve("懒加载的结果") }
}

_console.log("Deferred 已创建，但内部代码尚未执行。")
_console.log("任务状态: isActive=" + lazyDeferred.isActive() + ", isCompleted=" + lazyDeferred.isCompleted())

scope.delay(1000).then { s, _ -&gt;
    _console.log("\n1秒后... 准备启动任务...")

    // 手动启动任务
    lazyDeferred.start()
    // 或者，如果你需要结果，可以直接调用 .then()，它们会自动触发启动
    lazyDeferred
        .then { innerScope, result -&gt; result }
        .then { innerScope, result -&gt;
            _console.log("懒加载任务完成，结果是: " + result)
            innerScope.resolve(null)
        }
}
