<b>javascript</b> /*
 * 完整示例 6.4: 使用懒加载模式
 */

// --- 样板代码 ---
$threads.getMain().setBackground(true);
const scope = $coroutines.newScope(null);

$console.log("创建一个懒加载的 Deferred...");

// 使用 CoroutineStarts.getLazy() 来设置启动模式
const lazyDeferred = scope.async(null, starts =&gt; starts.getLazy(), s =&gt; {
    $console.log("懒加载的协程现在才真正开始执行！");
    return s.delay(1500).then((innerScope, _) =&gt; {
        return innerScope.resolve("懒加载的结果")
    });
});

$console.log("Deferred 已创建，但内部代码尚未执行。");
$console.log("任务状态: isActive=" + lazyDeferred.isActive() + ", isCompleted=" + lazyDeferred.isCompleted());

scope.delay(1000).then((s, _) =&gt; {
    $console.log("\n1秒后... 准备启动任务...");

    // 手动启动任务
    lazyDeferred.start();
    // 或者，如果你需要结果，可以直接调用 .then()，它们会自动触发启动
    return lazyDeferred
        .then((innerScope, result) =&gt; {
            // 根据API，then的处理器需要返回一个新的Deferred，这里我们用resolve包装结果
            return result;
        })
        .then((innerScope, result) =&gt; {
            $console.log("懒加载任务完成，结果是: " + result);
            return innerScope.resolve(null);
        });
}).onError(error =&gt; {
    $console.error("懒加载任务出错: " + error);
});
