默认情况下，Flow 的代码在收集它的协程的上下文中执行。flowOn 操作符是改变 Flow 上游执行线程的唯一正确方式。
<b>kotlin</b> import com.m8test.script.GlobalVariables.*

// 确保脚本在后台运行
_threads.getMain().setBackground(true)
val scope = _coroutines.newScope {
    setDispatcher { dispatchers -&gt; dispatchers.getScriptMain() }
}

_console.info("--- 章节 4：使用 flowOn 切换执行上下文 ---")

val logThread = { tag: String -&gt;
    _console.log("[${tag}] 当前线程: ${Thread.currentThread().name}")
}

_coroutines.getFlows().of("任务A", "任务B")
    .onEach { s, task -&gt;
        logThread("1. Flow 创建后 (上游)")
        s.resolve(null)
    }
// flowOn 将其上面的所有操作切换到 IO 线程池执行
    .flowOn {
        setDispatcher { it.getIO() }
    }
    .onEach { s, task -&gt;
        logThread("2. flowOn 之后 (下游)")
        s.resolve(null)
    }
    .collect(scope) { s, task -&gt;
        logThread("3. collect 内部 (收集器)")
        s.resolve(null)
    }
    .invokeOnCompletion {
        _console.info("可以看到，'上游'部分在IO线程执行，而'下游'和'收集器'在启动 collect 的主脚本线程执行。")
    }
