interval 可以创建一个按指定周期无限发出递增数字的 Flow。这对于模拟定时任务或事件流非常有用。由于它是无限的，我们需要手动管理其生命周期。
<b>kotlin</b> import com.m8test.script.GlobalVariables.*

// 确保脚本在后台运行
_threads.getMain().setBackground(true)
val scope = _coroutines.newScope(null)

_console.info("--- 章节 1.3：创建定时 Flow ---")

// 创建一个 Flow，延迟 1 秒后开始，之后每 2 秒发出一个递增的数字 (0, 1, 2, ...)
val intervalFlow = _coroutines.getFlows().interval(1000, 2000)

_console.log("定时 Flow 已创建，将在 1 秒后开始发射。")

// 使用 launchIn 在后台启动 Flow 的收集，它是一个“即发即忘”的终端操作符
val intervalJob = intervalFlow.launchIn(scope)

// 监听 Flow 中每个发出的值（使用 onEach 操作符，详见后续章节）
intervalFlow.onEach { s, tick -&gt;
    _console.log("Tick: ${tick}")
    s.resolve(null)
}.launchIn(scope)

_console.log("脚本将在 7 秒后取消协程作用域，停止定时 Flow。")

// 延迟 7 秒后取消整个作用域
scope.delay(7000).then { s, _ -&gt;
    _console.warn("正在取消作用域...")
    // 取消 scope 会自动取消所有在其内部启动的协程和 Flow
    scope.cancel("测试结束")
    _console.info("作用域已取消，定时 Flow 停止。")
    s.resolve(null)
}
