  $console.log("缓存未命中，从网络获取...")
  dataDeferred = scope.delay(5000).then { |s, _| s.async(nil, nil) { |ss| "从网络获取的数据" } }
end

dataDeferred.then do |s, data|
  $console.log("最终获取到的数据: " + data)
  s.resolve(nil)
end

$threads.getMain().setBackground(true)

