    providerSlot.CompositionLocalProvider {
        // 1. 根据名称获取之前创建的 CompositionLocal
        val localTestComposition: ProvidableCompositionLocal&lt;String&gt;? = getCompositionLocal("LocalTest")
        // 2. 提供值，通过 setValues 添加 provides 提供的值
        setValues(_iterables.listOf(localTestComposition!!.provides("LocalTextChangeValue2")))
        // 设置受嵌套 CompositionLocalProvider 影响的内容
        setContent {
            // 在插槽中添加一个文本
            Text {
                // 3. 消费值，这里就是 LocalTextChangeValue2
                setText(getCompositionLocalValue(localTestComposition)!!)
            }
        }
    }
}

