# 垂直方向上显示两个文本组件
# 在 Ruby 中，闭包（Block）通常作为最后一个隐式参数，或者显式声明为 &on_click
def ClickCounter(slot, clicks, &on_click)
  slot.Button do |button|
    # 在 Ruby 中调用传入的 Block
    button.setOnClick { on_click.call }
    button.setContent do |buttonSlot|
      buttonSlot.Text do |text|
        # 通过trackSingleState方法添加clicks,当clicks状态改变时, Text会重组
        text.trackSingleState(clicks)
        text.setText("Click me " + clicks.value.to_s)
      end
    end
  end
end

