// 垂直方向上显示两个文本组件
/** @param Slot $slot */
function Greeting($slot, string $name)
{
    $slot-&gt;Column(function ($column) use ($name) {
        // 设置 Column 的修饰符
        $column-&gt;setModifier(function ($modifier) {
            // 这里加个背景色是为了更好的展示效果
            $modifier-&gt;background(
