            $modifier-&gt;size(function ($it) {
                return $it-&gt;createSize($it-&gt;fromInt(200), $it-&gt;fromInt(100));
            });
        });
        $column-&gt;setContent(function ($columnSlot) use ($name) {
            $columnSlot-&gt;Text(function ($text) {
                // 设置 Text 组件显示的文本
                $text-&gt;setText(javaString("Hello"));
            });
            $columnSlot-&gt;Text(function ($text) use ($name) {
                // 设置 Text 组件显示的文本
                $text-&gt;setText($name);
                $text-&gt;setModifier(function ($modifier) {
                    $modifier-&gt;requiredSize(function ($it) {
                        return $it-&gt;createSize($it-&gt;fromInt(150), $it-&gt;fromInt(150));
                    });
