                        setOnClick { state.add("+++++") }
                    }
                }
                // 3. 将状态列表中的数据显示到 LazyColumn 中
                itemsIndexed(state, null, null) { index, item -&gt;
                    // 状态列表中每个元素显示一个简单的 Text 组件
                    Text {
                        setModifier {
                            height { d -&gt; d.fromInt(200) }
                        }
                        // 设置 Text 组件显示的内容
                        setText(item)
                    }
                }
            }
        }
    }
    // 启动一个Activity用于显示脚本界面
    _activity.start()
}
