      s3.loop do |s4|
        # 如果通道已经关闭直接退出循环
        if channel.isClosedForRead
          # 【修复】使用 next 代替 return 来从块中提前返回
          next s4.resolve(false)
        end
        channel.readAvailable(s4, buffer, 0, buffer.size).then do |s5, length|
          if length &lt;= 0
            # 【修复】使用 next 代替 return
