        "age": "INTEGER",
        "score": "REAL"
    }
    createRes = db.createTable(tableName, columns)
    assertLog("createTable", createRes, "True")

    # hasTable
    assertLog("hasTable", db.hasTable(tableName), "True")

    # ==========================================
