    user2 = {"name": "Bob", "age": 30, "score": 92.0}
    rowId2 = db.insert(tableName, None, user2)
    _console.log(f"插入 Bob, RowID: {rowId2}")

    if rowId1 != -1 and rowId2 != -1:
