    deleteRows = db.delete(tableName, "name = ?", _arrays.arrayOf(java_String, "Bob"))
    assertLog("delete (受影响行数)", deleteRows, 1)

    # ==========================================
    # 4. 原生 SQL 与 事务 (Transaction)
    # ==========================================
    _console.log("\n--- 测试 Transaction & execSQL ---")
    db.beginTransaction()
