_console.info("\n--- 开始示例 2.9: Iframe 上下文切换 ---")

// 1. 基础设置
val scope = _coroutines.newScope { setDispatcher { it.getIO() } }
val bridge = _webView.getBridge()
val controller = bridge.getController()
_activity.start()

