// **核心修正：使用 srcdoc 属性代替 src="data:..." 来确保同源**
// 注意：iframe_content 内部的属性使用双引号，以便 srcdoc 可以用单引号包围
val iframe_content = """&lt;button id="iframe-btn"&gt;Iframe里的按钮&lt;/button&gt;"""

val html = """
    &lt;html&gt;
        &lt;body&gt;
            &lt;h1&gt;主页面&lt;/h1&gt;
            &lt;iframe id="my-frame" srcdoc='$iframe_content'&gt;&lt;/iframe&gt;
        &lt;/body&gt;
    &lt;/html&gt;
"""
val iframeBtnXpath = "//*[@id='iframe-btn']"

// 3. 开始异步操作链
scope.delay(1000)
    .then { s, _ -&gt; controller.loadDataWithBaseURL(s, "https://iframe.test", html, null, null, "https://iframe.test") }
    .then { s, _ -&gt; s.delay(1000) } // 等待iframe渲染
    .then { s, _ -&gt;
        _console.log("切换前，尝试查找Iframe内的按钮...")
        controller.getElementCount(s, iframeBtnXpath)
    }
    .then { s, count -&gt;
        _console.log("切换前找到的数量:", count)
        _console.assertTrue(count == 0, "切换前不应找到Iframe内的元素")

        _console.log("切换到Iframe中...")
        controller.switchToFrame(s, "//*[@id='my-frame']")
    }
    .then { s, _ -&gt;
        _console.log("切换后，再次尝试查找Iframe内的按钮...")
        controller.getElementCount(s, iframeBtnXpath)
    }
    .then { s, count -&gt;
        _console.log("切换后找到的数量:", count)
        // 现在应该能正确找到了
        _console.assertTrue(count == 1, "切换后应找到Iframe内的元素")

        _console.log("切换回主内容...")
        controller.switchToDefaultContent(s)
    }
    .then { s, _ -&gt;
        _console.log("切回后，再次尝试查找Iframe内的按钮...")
        controller.getElementCount(s, iframeBtnXpath)
    }
    .then { s, count -&gt;
        _console.log("切回后找到的数量:", count)
        _console.assertTrue(count == 0, "切回后不应找到Iframe内的元素")
        _console.info("--- 示例 2.9: 成功 ---")
        s.resolve(null)
    }
    .onError { e -&gt; _console.error("--- 示例 2.9: 失败 ---", e.stackTraceToString()) }
